window.kbPageData["views/entry/k-958de1051c4f630c"] = {"key":"entry/k-958de1051c4f630c","state":{"route":"entry/k-958de1051c4f630c"},"node":{"id":"k-958de1051c4f630c","mode":"k","title":"党的建设","type":"概念与词义","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["party"],"主类":["概念与词义"],"出处性质":["机构注释"],"学科":["政治理论"],"来源主题":["党政制度与理论"],"资料类别":["非时政"]},"directorySummary":"2.党的建设\n党的建设是指党为保持自己的性质而从事的一系列自我完善的活动，不仅包括党\n务工作，还包括党的政治建设、思想建设、组织建设、作风建设、纪律建设和制度建\n设等。\n（1）党的政治建设：是党的根本性建设，决定党的建设方向和效果。党的政治建\n设的首要任务是保证全党服从中央，坚持党中央权威和集中统一…","sources":[{"id":"2979c5f4d345dad8","label":"党的建设","topic":"党政制度与理论","category":"非时政","text":"2.党的建设\n党的建设是指党为保持自己的性质而从事的一系列自我完善的活动，不仅包括党\n务工作，还包括党的政治建设、思想建设、组织建设、作风建设、纪律建设和制度建\n设等。\n（1）党的政治建设：是党的根本性建设，决定党的建设方向和效果。党的政治建\n设的首要任务是保证全党服从中央，坚持党中央权威和集中统一领导。\n（2）党的思想建设：是党的基础性建设。党的思想建设的首要任务是坚定理想信\n念。\n（3）新时代党的建设总要求是：坚持和加强党的全面领导，坚持党要管党、全面\n从严治党，以加强党的长期执政能力建设、先进性和纯洁性建设为主线，以党的政治\n建设为统领，以坚定理想信念宗旨为根基，以调动全党积极性、主动性、创造性为着\n力点，全面推进党的政治建设、思想建设、组织建设、作风建设、纪律建设，把制度\n建设贯穿其中，深入推进反腐败斗争，不断提高党的建设质量，把党建设成为始终走\n在时代前列、人民衷心拥护、勇于自我革命、经得起各种风浪考验、朝气蓬勃的马克\n思主义执政党。\n——《共产党员网》","source":{"doc":"41195a191a57c1c36332","first":6,"last":7,"page":6,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"party","title":"党的建设与自我革命"}],"units":{"k-958de1051c4f630c":[]}};
